/**
 * Python-style exception objects and traceback rendering.
 *
 * The original program lets exceptions escape to the interpreter, which prints
 * a traceback to stderr and exits with status 1.  We model exceptions as a
 * dedicated error class carrying the Python exception class name plus its
 * message so the top level can render an equivalent traceback.
 */

export class PyError extends Error {
  constructor(pyType, pyMessage, extra = {}) {
    super(pyMessage ? `${pyType}: ${pyMessage}` : pyType);
    this.name = pyType;
    this.pyType = pyType;
    this.pyMessage = pyMessage;
    // Extra frames rendered between the module frame and the exception line
    // (used to imitate the frames inside boltons / inside eval()).
    this.pyFrames = extra.frames || [];
  }

  /** The final line of a traceback: "TypeError: message" (or bare name). */
  get displayLine() {
    return this.pyMessage === '' || this.pyMessage === undefined
      ? this.pyType
      : `${this.pyType}: ${this.pyMessage}`;
  }
}

export const typeError = (msg, extra) => new PyError('TypeError', msg, extra);
export const valueError = (msg, extra) => new PyError('ValueError', msg, extra);
export const nameError = (msg, extra) => new PyError('NameError', msg, extra);
export const syntaxError = (msg, extra) => new PyError('SyntaxError', msg, extra);
export const zeroDivisionError = (msg, extra) => new PyError('ZeroDivisionError', msg, extra);
export const overflowError = (msg, extra) => new PyError('OverflowError', msg, extra);
export const indexError = (msg, extra) => new PyError('IndexError', msg, extra);
export const keyError = (msg, extra) => new PyError('KeyError', msg, extra);
export const attributeError = (msg, extra) => new PyError('AttributeError', msg, extra);

/**
 * Render a CPython 3.12 style traceback.
 *
 * @param {{file: string, line: number|null, name: string|null,
 *          source: string|null, caret: string|null}[]} frames
 *        Frames, outermost first.
 * @param {PyError} err
 */
export function formatTraceback(frames, err) {
  const out = ['Traceback (most recent call last):'];
  for (const frame of frames) {
    let header = `  File "${frame.file}"`;
    if (frame.line !== null && frame.line !== undefined) header += `, line ${frame.line}`;
    if (frame.name) header += `, in ${frame.name}`;
    out.push(header);
    if (frame.source) out.push(`    ${frame.source}`);
    if (frame.caret) out.push(`    ${frame.caret}`);
  }
  out.push(err.displayLine);
  return out.join('\n') + '\n';
}

