/**
 * Runtime model for Python values.
 *
 * Every Python object is represented as a tagged plain object so that the
 * distinction CPython makes between e.g. `2` and `2.0`, or `True` and `1`,
 * survives into printing and arithmetic.
 *
 *   int      { type: 'int',   value: BigInt }       arbitrary precision
 *   float    { type: 'float', value: Number }
 *   bool     { type: 'bool',  value: Boolean }
 *   None     { type: 'NoneType' }
 *   str      { type: 'str',   value: String }
 *   bytes    { type: 'bytes', value: Uint8Array }
 *   list     { type: 'list',  items: [] }
 *   tuple    { type: 'tuple', items: [] }
 *   set      { type: 'set' | 'frozenset', items: [] }   items in CPython order
 *   dict     { type: 'dict',  entries: [[key, value], ...] }
 *   range    { type: 'range', start, stop, step }        BigInt fields
 *   view     { type: 'dict_keys' | 'dict_values' | 'dict_items', items: [] }
 *   gen      { type: 'generator', iter, name }
 */

import { typeError } from './errors.mjs';

export const NONE = Object.freeze({ type: 'NoneType' });
export const TRUE = Object.freeze({ type: 'bool', value: true });
export const FALSE = Object.freeze({ type: 'bool', value: false });

export const int = (v) => ({ type: 'int', value: BigInt(v) });
export const float = (v) => ({ type: 'float', value: Number(v) });
export const bool = (v) => (v ? TRUE : FALSE);
export const str = (v) => ({ type: 'str', value: String(v) });
export const bytes = (v) => ({ type: 'bytes', value: v instanceof Uint8Array ? v : new Uint8Array(v) });
export const list = (items = []) => ({ type: 'list', items });
export const tuple = (items = []) => ({ type: 'tuple', items });
export const dict = (entries = []) => ({ type: 'dict', entries });
export const range = (start, stop, step) => ({
  type: 'range',
  start: BigInt(start),
  stop: BigInt(stop),
  step: BigInt(step),
});
export const view = (kind, items) => ({ type: kind, items });
export const generator = (iter, name = 'flatten_iter') => ({ type: 'generator', iter, name });

/** The name CPython uses for a value's type in error messages and reprs. */
export function typeName(v) {
  return v.type;
}

const ITERABLE_TYPES = new Set([
  'str', 'bytes', 'list', 'tuple', 'set', 'frozenset', 'dict', 'range',
  'dict_keys', 'dict_values', 'dict_items', 'generator',
]);

export const isIterable = (v) => ITERABLE_TYPES.has(v.type);

/** str / bytes: iterable, yet treated as scalars by boltons' flatten. */
export const isStringLike = (v) => v.type === 'str' || v.type === 'bytes';

export const isNumber = (v) => v.type === 'int' || v.type === 'float' || v.type === 'bool';

/** Numeric value of an int/bool as BigInt. */
export const asBigInt = (v) => (v.type === 'bool' ? (v.value ? 1n : 0n) : v.value);

/** Numeric value of any number-ish value as a JS Number. */
export const asNumber = (v) =>
  v.type === 'float' ? v.value : Number(asBigInt(v));

/** Python's iteration protocol.  Yields Python values. */
export function* pyIter(v) {
  switch (v.type) {
    case 'str':
      // Python iterates code points, which is what for..of does.
      for (const ch of v.value) yield str(ch);
      return;
    case 'bytes':
      for (const b of v.value) yield int(b);
      return;
    case 'list':
    case 'tuple':
      yield* v.items;
      return;
    case 'set':
    case 'frozenset':
    case 'dict_keys':
    case 'dict_values':
    case 'dict_items':
      yield* v.items;
      return;
    case 'dict':
      for (const [k] of v.entries) yield k;
      return;
    case 'range': {
      const { start, stop, step } = v;
      if (step > 0n) for (let i = start; i < stop; i += step) yield int(i);
      else for (let i = start; i > stop; i += step) yield int(i);
      return;
    }
    case 'generator':
      yield* v.iter;
      return;
    default:
      throw typeError(`'${typeName(v)}' object is not iterable`);
  }
}

/** Materialise an iterable into a JS array of Python values. */
export const iterToArray = (v) => Array.from(pyIter(v));

/** Python `==` for the value kinds this program can produce. */
export function pyEq(a, b) {
  if (a === b) return true;
  const an = isNumber(a);
  const bn = isNumber(b);
  if (an && bn) {
    if (a.type === 'float' || b.type === 'float') {
      const x = asNumber(a);
      const y = asNumber(b);
      // NaN never equals anything, including itself.
      return x === y;
    }
    return asBigInt(a) === asBigInt(b);
  }
  if (an !== bn) return false;
  if (a.type !== b.type) {
    const setish = (t) => t === 'set' || t === 'frozenset';
    if (!(setish(a.type) && setish(b.type))) return false;
  }
  switch (a.type) {
    case 'NoneType':
      return true;
    case 'str':
      return a.value === b.value;
    case 'bytes':
      if (a.value.length !== b.value.length) return false;
      for (let i = 0; i < a.value.length; i++) if (a.value[i] !== b.value[i]) return false;
      return true;
    case 'list':
    case 'tuple':
      if (a.items.length !== b.items.length) return false;
      return a.items.every((x, i) => pyEq(x, b.items[i]));
    case 'set':
    case 'frozenset':
      if (a.items.length !== b.items.length) return false;
      return a.items.every((x) => b.items.some((y) => pyEq(x, y)));
    case 'dict':
      if (a.entries.length !== b.entries.length) return false;
      return a.entries.every(([k, v]) => {
        const hit = b.entries.find(([k2]) => pyEq(k, k2));
        return hit !== undefined && pyEq(v, hit[1]);
      });
    case 'range':
      return a.start === b.start && a.stop === b.stop && a.step === b.step;
    default:
      return false;
  }
}

/** Python truthiness. */
export function pyTruth(v) {
  switch (v.type) {
    case 'NoneType':
      return false;
    case 'bool':
      return v.value;
    case 'int':
      return v.value !== 0n;
    case 'float':
      return v.value !== 0;
    case 'str':
      return v.value.length > 0;
    case 'bytes':
      return v.value.length > 0;
    case 'list':
    case 'tuple':
    case 'set':
    case 'frozenset':
    case 'dict_keys':
    case 'dict_values':
    case 'dict_items':
      return v.items.length > 0;
    case 'dict':
      return v.entries.length > 0;
    case 'range':
      return rangeLength(v) > 0n;
    default:
      return true;
  }
}

export function rangeLength(r) {
  const { start, stop, step } = r;
  if (step > 0n) return stop > start ? (stop - start + step - 1n) / step : 0n;
  return stop < start ? (start - stop + (-step) - 1n) / (-step) : 0n;
}

