/**
 * CPython's hash functions, reimplemented so that set iteration order can be
 * reproduced exactly (see pyset.mjs).
 *
 * Hashes of `str`/`bytes` are salted with a per-process random seed in CPython,
 * so those are reported as non-deterministic and callers fall back to insertion
 * order for such containers.
 */

const MODULUS = (1n << 61n) - 1n; // _PyHASH_MODULUS
const BITS = 61n; // _PyHASH_BITS
const U64 = (1n << 64n) - 1n;
const SIGN_BIT = 1n << 63n;

const XXPRIME_1 = 11400714785074694791n;
const XXPRIME_2 = 14029467366897019727n;
const XXPRIME_5 = 2870177450012600261n;

export const toUnsigned64 = (h) => h & U64;
export const toSigned64 = (u) => ((u &= U64), u >= SIGN_BIT ? u - (1n << 64n) : u);

/** C's frexp: returns [mantissa in [0.5, 1), exponent] with v = m * 2**e. */
function frexp(v) {
  if (v === 0 || !Number.isFinite(v)) return [v, 0];
  const dv = new DataView(new ArrayBuffer(8));
  dv.setFloat64(0, v);
  let hi = dv.getUint32(0);
  let biased = (hi >>> 20) & 0x7ff;
  let extra = 0;
  if (biased === 0) {
    // Subnormal: scale by 2**64 (exact) to normalise first.
    dv.setFloat64(0, v * 18446744073709551616);
    hi = dv.getUint32(0);
    biased = (hi >>> 20) & 0x7ff;
    extra = -64;
  }
  const e = biased - 1022 + extra;
  hi = (hi & 0x800fffff) | (1022 << 20);
  dv.setUint32(0, hi);
  return [dv.getFloat64(0), e];
}

/** _Py_HashDouble */
function hashDouble(v) {
  if (!Number.isFinite(v)) {
    if (Number.isNaN(v)) return null; // hashes by object identity since 3.10
    return v > 0 ? 314159n : -314159n;
  }
  let [m, e] = frexp(v);
  let sign = 1n;
  if (m < 0) {
    sign = -1n;
    m = -m;
  }
  let x = 0n;
  while (m !== 0) {
    x = ((x << 28n) & MODULUS) | (x >> (BITS - 28n));
    m *= 268435456.0; // 2**28
    e -= 28;
    const y = Math.trunc(m);
    m -= y;
    x += BigInt(y);
    if (x >= MODULUS) x -= MODULUS;
  }
  const shift = BigInt(e >= 0 ? e % 61 : 60 - ((-1 - e) % 61));
  x = ((x << shift) & MODULUS) | (x >> (BITS - shift));
  let h = x * sign;
  if (h === -1n) h = -2n;
  return h;
}

/** long_hash */
function hashBigInt(n) {
  const neg = n < 0n;
  let h = (neg ? -n : n) % MODULUS;
  if (neg) h = -h;
  if (h === -1n) h = -2n;
  return h;
}

/** tuplehash (xxHash based, not salted) */
function hashTuple(items) {
  let acc = XXPRIME_5;
  for (const item of items) {
    const lane = pyHash(item);
    if (lane === null) return null;
    acc = (acc + toUnsigned64(lane) * XXPRIME_2) & U64;
    acc = ((acc << 31n) | (acc >> 33n)) & U64; // XXROTATE
    acc = (acc * XXPRIME_1) & U64;
  }
  acc = (acc + (BigInt(items.length) ^ (XXPRIME_5 ^ 3527539n))) & U64;
  if (acc === U64) return 1546275796n;
  return toSigned64(acc);
}

/**
 * Hash of a Python value as a signed 64-bit BigInt, or `null` when CPython's
 * value is process-dependent (str, bytes, NaN, ...).
 */
export function pyHash(v) {
  switch (v.type) {
    case 'int':
      return hashBigInt(v.value);
    case 'bool':
      return v.value ? 1n : 0n;
    case 'float':
      return hashDouble(v.value);
    case 'NoneType':
      return 0xfca86420n; // constant since CPython 3.12
    case 'tuple':
      return hashTuple(v.items);
    default:
      return null; // salted (str/bytes) or unhashable
  }
}

export const isDeterministicHash = (v) => pyHash(v) !== null;

