  if (v === 0 || !Number.isFinite(v)) return [v, 0];
  const dv = new DataView(new ArrayBuffer(8));
  dv.setFloat64(0, v);
  let hi = dv.getUint32(0);
  let biased = (hi >>> 20) & 0x7ff;
  let extra = 0;
  if (biased === 0) {
    // Subnormal: scale by 2**64 (exact) to normalise first.
    dv.setFloat64(0, v * 18446744073709551616);
    hi = dv.getUint32(0);
    biased = (hi >>> 20) & 0x7ff;
    extra = -64;
  }
  const e = biased - 1022 + extra;
  hi = (hi & 0x800fffff) | (1022 << 20);
  dv.setUint32(0, hi);
  return [dv.getFloat64(0), e];
}

/** _Py_HashDouble */
function hashDouble(v) {
