  if (h === -1n) h = -2n;
  return h;
}

/** long_hash */
function hashBigInt(n) {
  const neg = n < 0n;
  let h = (neg ? -n : n) % MODULUS;
  if (neg) h = -h;
  if (h === -1n) h = -2n;
  return h;
}

/** tuplehash (xxHash based, not salted) */
function hashTuple(items) {
  let acc = XXPRIME_5;
  for (const item of items) {
    const lane = pyHash(item);
    if (lane === null) return null;
    acc = (acc + toUnsigned64(lane) * XXPRIME_2) & U64;
    acc = ((acc << 31n) | (acc >> 33n)) & U64; // XXROTATE
    acc = (acc * XXPRIME_1) & U64;
  }
  acc = (acc + (BigInt(items.length) ^ (XXPRIME_5 ^ 3527539n))) & U64;
