  if (elements.length > 2 && allConstant) {
    const folded = makeSetValue(elements, { frozen: true });
    return makeSetValue(folded.items, { frozen: false, presizeFrom: folded.items.length });
  }
  return makeSetValue(elements, { frozen: false });
}

/** set()/frozenset() over an iterable that has already been materialised. */
export function setFromItems(items, { frozen = false, sourceIsHashTable = false } = {}) {
  return makeSetValue(items, { frozen, presizeFrom: sourceIsHashTable ? items.length : null });
}

