/**
 * `repr()` / `str()` for the Python value model, matching CPython 3.12 output.
 */

const NON_PRINTABLE_RANGES = [
  // Approximation of Py_UNICODE_ISPRINTABLE() == 0 for the characters that
  // realistically show up: C0/C1 controls, separators and format characters.
  [0x00, 0x1f], [0x7f, 0xa0], [0xad, 0xad], [0x0600, 0x0605], [0x061c, 0x061c],
  [0x06dd, 0x06dd], [0x070f, 0x070f], [0x180e, 0x180e], [0x2000, 0x200f],
  [0x2028, 0x202f], [0x205f, 0x2064], [0x2066, 0x206f], [0x3000, 0x3000],
  [0xd800, 0xdfff], [0xfeff, 0xfeff], [0xfff9, 0xfffb],
];

const isPrintable = (cp) =>
  !NON_PRINTABLE_RANGES.some(([lo, hi]) => cp >= lo && cp <= hi);

/** repr() of a float: shortest round-trip digits, CPython's formatting rules. */
export function floatRepr(value) {
  if (Number.isNaN(value)) return 'nan';
  if (value === Infinity) return 'inf';
  if (value === -Infinity) return '-inf';
  const sign = value < 0 || Object.is(value, -0) ? '-' : '';
  const abs = Math.abs(value);
  if (abs === 0) return `${sign}0.0`;

  // toExponential() without an argument yields the shortest digit string that
  // round-trips, which is exactly what repr() uses.
  const [mantissa, expPart] = abs.toExponential().split('e');
  const digits = mantissa.replace('.', '');
  const decpt = Number(expPart) + 1; // value === 0.<digits> * 10**decpt

  if (decpt <= -4 || decpt > 16) {
    const exp = decpt - 1;
    const head = digits.length > 1 ? `${digits[0]}.${digits.slice(1)}` : digits;
    const expSign = exp < 0 ? '-' : '+';
    const expDigits = String(Math.abs(exp)).padStart(2, '0');
    return `${sign}${head}e${expSign}${expDigits}`;
  }
  if (decpt <= 0) return `${sign}0.${'0'.repeat(-decpt)}${digits}`;
  if (decpt >= digits.length) return `${sign}${digits}${'0'.repeat(decpt - digits.length)}.0`;
  return `${sign}${digits.slice(0, decpt)}.${digits.slice(decpt)}`;
}

const pickQuote = (hasSingle, hasDouble) => (hasSingle && !hasDouble ? '"' : "'");

export function strRepr(s) {
  const quote = pickQuote(s.includes("'"), s.includes('"'));
  let out = quote;
  for (const ch of s) {
    const cp = ch.codePointAt(0);
    if (ch === quote || ch === '\\') out += `\\${ch}`;
    else if (ch === '\t') out += '\\t';
    else if (ch === '\n') out += '\\n';
    else if (ch === '\r') out += '\\r';
    else if (isPrintable(cp)) out += ch;
    else if (cp < 0x100) out += `\\x${cp.toString(16).padStart(2, '0')}`;
    else if (cp < 0x10000) out += `\\u${cp.toString(16).padStart(4, '0')}`;
    else out += `\\U${cp.toString(16).padStart(8, '0')}`;
  }
  return out + quote;
}

export function bytesRepr(u8) {
  const chars = Array.from(u8, (b) => String.fromCharCode(b));
  const quote = pickQuote(chars.includes("'"), chars.includes('"'));
  let out = `b${quote}`;
  for (const b of u8) {
    const ch = String.fromCharCode(b);
    if (ch === quote || ch === '\\') out += `\\${ch}`;
    else if (b === 9) out += '\\t';
    else if (b === 10) out += '\\n';
    else if (b === 13) out += '\\r';
    else if (b >= 0x20 && b < 0x7f) out += ch;
    else out += `\\x${b.toString(16).padStart(2, '0')}`;
  }
  return out + quote;
}

export function pyRepr(v) {
  switch (v.type) {
    case 'int':
      return v.value.toString();
    case 'float':
      return floatRepr(v.value);
    case 'bool':
      return v.value ? 'True' : 'False';
    case 'NoneType':
      return 'None';
    case 'str':
      return strRepr(v.value);
    case 'bytes':
      return bytesRepr(v.value);
    case 'list':
      return `[${v.items.map(pyRepr).join(', ')}]`;
    case 'tuple':
      if (v.items.length === 1) return `(${pyRepr(v.items[0])},)`;
      return `(${v.items.map(pyRepr).join(', ')})`;
    case 'set':
      return v.items.length === 0 ? 'set()' : `{${v.items.map(pyRepr).join(', ')}}`;
    case 'frozenset':
      return v.items.length === 0
        ? 'frozenset()'
        : `frozenset({${v.items.map(pyRepr).join(', ')}})`;
    case 'dict':
      return `{${v.entries.map(([k, val]) => `${pyRepr(k)}: ${pyRepr(val)}`).join(', ')}}`;
    case 'range':
      return v.step === 1n
        ? `range(${v.start}, ${v.stop})`
        : `range(${v.start}, ${v.stop}, ${v.step})`;
    case 'dict_keys':
    case 'dict_values':
      return `${v.type}([${v.items.map(pyRepr).join(', ')}])`;
    case 'dict_items':
      return `dict_items([${v.items.map(pyRepr).join(', ')}])`;
    case 'generator':
      return `<generator object ${v.name} at 0x7f0000000000>`;
    default:
      return `<${v.type} object>`;
  }
}

/** str(): identical to repr() except that strings are returned verbatim. */
export const pyStr = (v) => (v.type === 'str' ? v.value : pyRepr(v));

