/**
 * boltons.iterutils, reimplemented from observed behaviour.
 *
 *   flatten_iter / flatten  – recursively expand nested iterables, treating
 *                             str and bytes as scalars.
 *   chunked_iter / chunked  – slice an iterable into lists of `size` items,
 *                             the final chunk being short unless `fill` given.
 */

import { typeError, valueError } from '../errors.mjs';
import { list, str, pyIter, isIterable, isStringLike, typeName } from '../values.mjs';

/** boltons.iterutils.is_iterable */
export const isIterableValue = (v) => isIterable(v);

/**
 * Depth-first expansion.  Raises TypeError when the argument itself is not
 * iterable — the message comes from the `for item in iterable` loop, e.g.
 * "'int' object is not iterable".
 */
export function* flattenIter(iterable) {
  for (const item of pyIter(iterable)) {
    if (isIterable(item) && !isStringLike(item)) yield* flattenIter(item);
    else yield item;
  }
}

/** Returns a Python list, as boltons' flatten() does. */
export function flatten(iterable) {
  return list([...flattenIter(iterable)]);
}

/**
 * @param {object} src   Python iterable
 * @param {number} size  positive chunk size
 * @param {{fill?: object}} [opts]  when `fill` is present short chunks are padded
 */
export function* chunkedIter(src, size, opts = {}) {
  if (!isIterable(src)) throw typeError('expected an iterable');
  if (!Number.isInteger(size)) throw typeError(`'${typeName(src)}' object cannot be interpreted as an integer`);
  if (size <= 0) throw valueError(`expected a positive integer size, not ${size}`);
  const hasFill = Object.prototype.hasOwnProperty.call(opts, 'fill');
  // Chunking a string yields strings rather than lists of characters.
  const joinBack = src.type === 'str';
  const iterator = pyIter(src);
  for (;;) {
    const chunk = [];
    for (let i = 0; i < size; i++) {
      const next = iterator.next();
      if (next.done) break;
      chunk.push(next.value);
    }
    if (chunk.length === 0) return;
    if (chunk.length < size && hasFill) {
      while (chunk.length < size) chunk.push(opts.fill);
    }
    yield joinBack ? str(chunk.map((c) => c.value).join('')) : list(chunk);
  }
}

/** Returns a Python list of chunks, as boltons' chunked() does. */
export function chunked(src, size, opts = {}) {
  return list([...chunkedIter(src, size, opts)]);
}

