/**
 * Tokenizer for the subset of Python expression syntax accepted by eval().
 */

import { syntaxError, valueError } from '../errors.mjs';
import { int, float, str, bytes } from '../values.mjs';

const OPERATORS = [
  '**=', '//=', '>>=', '<<=', '...',
  '**', '//', '<<', '>>', '<=', '>=', '==', '!=', ':=', '->',
  '+', '-', '*', '/', '%', '@', '&', '|', '^', '~', '<', '>',
  '(', ')', '[', ']', '{', '}', ',', ':', '.', '=', ';',
];

const KEYWORDS = new Set([
  'and', 'or', 'not', 'in', 'is', 'if', 'else', 'for', 'lambda', 'None', 'True', 'False',
]);

const isDigit = (ch) => ch >= '0' && ch <= '9';
const isIdentStart = (ch) => /[A-Za-z_-￿]/.test(ch);
const isIdentPart = (ch) => /[A-Za-z0-9_-￿]/.test(ch);

const OPENERS = { '(': ')', '[': ']', '{': '}' };

export function tokenize(src) {
  const tokens = [];
  const stack = [];
  let i = 0;

  const push = (kind, value, extra = {}) => tokens.push({ kind, value, start: i, ...extra });

  while (i < src.length) {
    const ch = src[i];

    if (ch === '\\' && (src[i + 1] === '\n' || src[i + 1] === '\r')) {
      i += src[i + 1] === '\r' && src[i + 2] === '\n' ? 3 : 2;
      continue;
    }
    if (ch === ' ' || ch === '\t' || ch === '\f' || ch === '\n' || ch === '\r') {
      i++;
      continue;
    }
    if (ch === '#') {
      while (i < src.length && src[i] !== '\n') i++;
      continue;
    }

    // String / bytes literal, possibly prefixed.
    const prefixMatch = /^(?:[rRbBuUfF]{1,3})?(?:'''|"""|'|")/.exec(src.slice(i));
    if (prefixMatch && /['"]/.test(prefixMatch[0].slice(-1))) {
      const prefix = prefixMatch[0].replace(/['"]+$/, '').toLowerCase();
      if (prefix.includes('f')) throw syntaxError('f-string expressions are not supported');
      const quoteStart = i + prefix.length;
      const quote = src.startsWith('"""', quoteStart)
        ? '"""'
        : src.startsWith("'''", quoteStart)
          ? "'''"
          : src[quoteStart];
      const bodyStart = quoteStart + quote.length;
      const end = findStringEnd(src, bodyStart, quote, prefix.includes('r'));
      const body = src.slice(bodyStart, end);
      const isBytes = prefix.includes('b');
      const decoded = prefix.includes('r') ? body : unescape(body, isBytes);
      const startPos = i;
      i = end + quote.length;
      tokens.push({
        kind: isBytes ? 'bytes' : 'str',
        value: decoded,
        pyValue: isBytes ? bytes(toByteArray(decoded)) : str(decoded),
        start: startPos,
      });
      continue;
    }

    if (isDigit(ch) || (ch === '.' && isDigit(src[i + 1]))) {
      const { token, next } = readNumber(src, i);
      tokens.push({ ...token, start: i });
      i = next;
      continue;
    }

    if (isIdentStart(ch)) {
      let j = i;
      while (j < src.length && isIdentPart(src[j])) j++;
      const word = src.slice(i, j);
      tokens.push({ kind: KEYWORDS.has(word) ? 'keyword' : 'name', value: word, start: i });
      i = j;
      continue;
    }

    const op = OPERATORS.find((candidate) => src.startsWith(candidate, i));
    if (op) {
      if (OPENERS[op]) stack.push({ op, pos: i });
      else if (op === ')' || op === ']' || op === '}') {
        const top = stack.pop();
        if (!top || OPENERS[top.op] !== op) {
          throw syntaxError(`unmatched '${op}'`);
        }
      }
      push('op', op);
      i += op.length;
      continue;
    }

    throw syntaxError(`invalid character '${ch}' (U+${ch.codePointAt(0).toString(16).toUpperCase().padStart(4, '0')})`);
  }

  if (stack.length > 0) {
    throw syntaxError(`'${stack[stack.length - 1].op}' was never closed`);
  }
