  return tokens;
}

function findStringEnd(src, from, quote, raw) {
  let i = from;
  while (i < src.length) {
    if (!raw && src[i] === '\\') {
      i += 2;
      continue;
    }
    if (raw && src[i] === '\\' && src[i + 1] === quote[0]) {
      i += 2;
      continue;
    }
    if (src.startsWith(quote, i)) return i;
    if (src[i] === '\n' && quote.length === 1) {
      throw syntaxError('unterminated string literal (detected at line 1)');
    }
    i++;
  }
  throw syntaxError(
    quote.length === 3
      ? 'unterminated triple-quoted string literal (detected at line 1)'
      : 'unterminated string literal (detected at line 1)'
  );
}

