  while (i < body.length) {
    const ch = body[i];
    if (ch !== '\\') {
      out += ch;
      i++;
      continue;
    }
    const next = body[i + 1];
    if (next === undefined) {
      out += '\\';
      break;
    }
    if (next === '\n') {
      i += 2;
      continue;
    }
    if (next >= '0' && next <= '7') {
      let digits = '';
      let j = i + 1;
      while (j < body.length && digits.length < 3 && body[j] >= '0' && body[j] <= '7') {
        digits += body[j];
