/**
 * Recursive-descent parser producing a small AST for Python expressions.
 *
 * Precedence, lowest to highest:
 *   conditional -> or -> and -> not -> comparison -> | -> ^ -> & -> shifts
 *   -> +,- -> *,/,//,% -> unary -> ** -> trailers (call/index/attribute)
 */

import { syntaxError } from '../errors.mjs';

const COMPARISON_OPS = new Set(['==', '!=', '<', '>', '<=', '>=']);

export function parse(tokens) {
  const state = { tokens, pos: 0 };
  const node = parseExpressionList(state);
  expect(state, 'eof');
  return node;
}

const peek = (state, offset = 0) => state.tokens[state.pos + offset];
const at = (state, kind, value) => {
  const token = peek(state);
  return token.kind === kind && (value === undefined || token.value === value);
};
const atOp = (state, value) => at(state, 'op', value);
const atKeyword = (state, value) => at(state, 'keyword', value);

function next(state) {
  return state.tokens[state.pos++];
}

function expect(state, kind, value) {
  if (!at(state, kind, value)) {
    const token = peek(state);
    throw syntaxError(token.kind === 'eof' ? 'invalid syntax' : 'invalid syntax');
  }
  return next(state);
}

function accept(state, kind, value) {
  if (at(state, kind, value)) return next(state);
  return null;
}

/** `a, b, c` at the top level builds a tuple. */
function parseExpressionList(state) {
  const first = parseConditional(state);
  if (!atOp(state, ',')) return first;
  const elts = [first];
  while (accept(state, 'op', ',')) {
    if (at(state, 'eof')) break;
    elts.push(parseConditional(state));
  }
  return { k: 'Tuple', elts };
}

function parseConditional(state) {
  const body = parseOr(state);
  if (atKeyword(state, 'if')) {
    next(state);
    const test = parseOr(state);
    expect(state, 'keyword', 'else');
    const orelse = parseConditional(state);
    return { k: 'IfExp', test, body, orelse };
  }
  return body;
}

function parseOr(state) {
  let left = parseAnd(state);
  while (atKeyword(state, 'or')) {
    next(state);
    left = { k: 'BoolOp', op: 'or', left, right: parseAnd(state) };
  }
  return left;
}

function parseAnd(state) {
  let left = parseNot(state);
  while (atKeyword(state, 'and')) {
    next(state);
    left = { k: 'BoolOp', op: 'and', left, right: parseNot(state) };
  }
  return left;
}

function parseNot(state) {
  if (atKeyword(state, 'not')) {
    next(state);
    return { k: 'Not', operand: parseNot(state) };
  }
  return parseComparison(state);
}

function parseComparison(state) {
  const left = parseBitOr(state);
  const ops = [];
  const comparators = [];
  for (;;) {
    let op = null;
    if (at(state, 'op') && COMPARISON_OPS.has(peek(state).value)) op = next(state).value;
    else if (atKeyword(state, 'in')) {
      next(state);
      op = 'in';
    } else if (atKeyword(state, 'not') && peek(state, 1).kind === 'keyword' && peek(state, 1).value === 'in') {
      next(state);
      next(state);
      op = 'not in';
    } else if (atKeyword(state, 'is')) {
      next(state);
      op = accept(state, 'keyword', 'not') ? 'is not' : 'is';
    }
    if (op === null) break;
    ops.push(op);
    comparators.push(parseBitOr(state));
  }
  if (ops.length === 0) return left;
  return { k: 'Compare', left, ops, comparators };
}

const binaryLevel = (parseNext, operators) => (state) => {
  let left = parseNext(state);
  while (at(state, 'op') && operators.includes(peek(state).value)) {
    const op = next(state).value;
    left = { k: 'BinOp', op, left, right: parseNext(state) };
  }
  return left;
};

const parseShift = (state) => binaryLevel(parseArith, ['<<', '>>'])(state);
const parseBitAnd = (state) => binaryLevel(parseShift, ['&'])(state);
const parseBitXor = (state) => binaryLevel(parseBitAnd, ['^'])(state);
const parseBitOr = (state) => binaryLevel(parseBitXor, ['|'])(state);

function parseArith(state) {
  return binaryLevel(parseTerm, ['+', '-'])(state);
}

function parseTerm(state) {
  return binaryLevel(parseUnary, ['*', '/', '//', '%', '@'])(state);
}

function parseUnary(state) {
  if (at(state, 'op') && ['+', '-', '~'].includes(peek(state).value)) {
    const op = next(state).value;
    return { k: 'UnaryOp', op, operand: parseUnary(state) };
  }
  return parsePower(state);
}

function parsePower(state) {
  const base = parsePostfix(state);
  if (atOp(state, '**')) {
    next(state);
    // ** binds tighter than unary minus on its left, looser on its right.
    return { k: 'BinOp', op: '**', left: base, right: parseUnary(state) };
  }
  return base;
}

function parsePostfix(state) {
  let node = parseAtom(state);
  for (;;) {
    if (atOp(state, '(')) {
      next(state);
      const args = [];
      const keywords = [];
      while (!atOp(state, ')')) {
        if (at(state, 'name') && peek(state, 1).kind === 'op' && peek(state, 1).value === '=') {
          const name = next(state).value;
          next(state);
          keywords.push({ name, value: parseConditional(state) });
        } else if (atOp(state, '*')) {
          next(state);
          args.push({ k: 'Starred', value: parseConditional(state) });
        } else {
          args.push(parseConditional(state));
        }
        if (!accept(state, 'op', ',')) break;
      }
      expect(state, 'op', ')');
      node = { k: 'Call', func: node, args, keywords };
      continue;
    }
    if (atOp(state, '[')) {
      next(state);
      const index = parseSubscript(state);
      expect(state, 'op', ']');
      node = { k: 'Subscript', value: node, index };
      continue;
    }
    if (atOp(state, '.')) {
      next(state);
      const attr = expect(state, 'name').value;
      node = { k: 'Attribute', value: node, attr };
      continue;
    }
    return node;
  }
}

function parseSubscript(state) {
  const part = () => (atOp(state, ':') || atOp(state, ']') ? null : parseConditional(state));
  const lower = part();
  if (!atOp(state, ':')) return { k: 'Index', value: lower };
  next(state);
  const upper = part();
  let step = null;
  if (accept(state, 'op', ':')) step = part();
  return { k: 'Slice', lower, upper, step };
}

/** for-clauses of a comprehension, if present. */
function parseComprehensionClauses(state) {
  const generators = [];
  while (atKeyword(state, 'for')) {
    next(state);
    const target = parseTargetList(state);
    expect(state, 'keyword', 'in');
    const iter = parseOr(state);
    const ifs = [];
    while (atKeyword(state, 'if')) {
      next(state);
      ifs.push(parseOr(state));
    }
    generators.push({ target, iter, ifs });
  }
  return generators;
}

function parseTargetList(state) {
  const targets = [parseTarget(state)];
  while (atOp(state, ',')) {
    next(state);
    if (atKeyword(state, 'in')) break;
    targets.push(parseTarget(state));
  }
  return targets.length === 1 ? targets[0] : { k: 'TupleTarget', elts: targets };
}

function parseTarget(state) {
  if (atOp(state, '(') || atOp(state, '[')) {
    const close = atOp(state, '(') ? ')' : ']';
    next(state);
    const elts = [];
    while (!atOp(state, close)) {
      elts.push(parseTarget(state));
      if (!accept(state, 'op', ',')) break;
    }
    expect(state, 'op', close);
    return { k: 'TupleTarget', elts };
  }
  const name = expect(state, 'name').value;
  return { k: 'NameTarget', id: name };
}

function parseAtom(state) {
  const token = peek(state);
  switch (token.kind) {
    case 'num':
      next(state);
      return { k: 'Const', value: token.pyValue };
    case 'str':
    case 'bytes': {
      // Adjacent literals concatenate.
      let value = next(state).pyValue;
      while (at(state, token.kind)) {
        const more = next(state).pyValue;
        if (value.type === 'str') value = { type: 'str', value: value.value + more.value };
        else {
          const merged = new Uint8Array(value.value.length + more.value.length);
          merged.set(value.value);
          merged.set(more.value, value.value.length);
          value = { type: 'bytes', value: merged };
        }
      }
      return { k: 'Const', value };
    }
    case 'name':
      next(state);
      return { k: 'Name', id: token.value };
    case 'keyword':
      if (['None', 'True', 'False'].includes(token.value)) {
        next(state);
        return { k: 'Name', id: token.value };
      }
      if (token.value === 'lambda') throw syntaxError('lambda expressions are not supported');
      throw syntaxError('invalid syntax');
    case 'op':
      if (token.value === '(') return parseParenthesized(state);
      if (token.value === '[') return parseListDisplay(state);
      if (token.value === '{') return parseBraceDisplay(state);
      if (token.value === '...') {
        next(state);
        return { k: 'Name', id: 'Ellipsis' };
      }
      throw syntaxError('invalid syntax');
    default:
      throw syntaxError('invalid syntax');
  }
}

function parseParenthesized(state) {
  expect(state, 'op', '(');
  if (atOp(state, ')')) {
    next(state);
    return { k: 'Tuple', elts: [] };
  }
  const first = parseConditional(state);
  if (atKeyword(state, 'for')) {
    const generators = parseComprehensionClauses(state);
    expect(state, 'op', ')');
    return { k: 'GenExp', elt: first, generators };
  }
  if (atOp(state, ',')) {
    const elts = [first];
    while (accept(state, 'op', ',')) {
      if (atOp(state, ')')) break;
      elts.push(parseConditional(state));
    }
    expect(state, 'op', ')');
    return { k: 'Tuple', elts };
  }
  expect(state, 'op', ')');
  return { k: 'Paren', value: first };
}

function parseListDisplay(state) {
  expect(state, 'op', '[');
  if (atOp(state, ']')) {
    next(state);
    return { k: 'List', elts: [] };
  }
  const first = parseConditional(state);
  if (atKeyword(state, 'for')) {
    const generators = parseComprehensionClauses(state);
    expect(state, 'op', ']');
    return { k: 'ListComp', elt: first, generators };
  }
  const elts = [first];
  while (accept(state, 'op', ',')) {
    if (atOp(state, ']')) break;
    elts.push(parseConditional(state));
  }
  expect(state, 'op', ']');
  return { k: 'List', elts };
}

function parseBraceDisplay(state) {
  expect(state, 'op', '{');
  if (atOp(state, '}')) {
    next(state);
    return { k: 'Dict', keys: [], values: [] };
  }
  const first = parseConditional(state);
  if (atOp(state, ':')) {
    next(state);
    const firstValue = parseConditional(state);
    if (atKeyword(state, 'for')) {
      const generators = parseComprehensionClauses(state);
      expect(state, 'op', '}');
      return { k: 'DictComp', key: first, value: firstValue, generators };
    }
    const keys = [first];
    const values = [firstValue];
    while (accept(state, 'op', ',')) {
      if (atOp(state, '}')) break;
      keys.push(parseConditional(state));
      expect(state, 'op', ':');
      values.push(parseConditional(state));
    }
    expect(state, 'op', '}');
    return { k: 'Dict', keys, values };
  }
  if (atKeyword(state, 'for')) {
    const generators = parseComprehensionClauses(state);
    expect(state, 'op', '}');
    return { k: 'SetComp', elt: first, generators };
  }
  const elts = [first];
  while (accept(state, 'op', ',')) {
    if (atOp(state, '}')) break;
    elts.push(parseConditional(state));
  }
  expect(state, 'op', '}');
  return { k: 'Set', elts };
}

