/**
 * The builtin functions eval()'d expressions may reference.
 *
 * A callable is modelled as { type: 'builtin_function', name, call }.
 */

import { typeError, valueError, overflowError } from '../errors.mjs';
import {
  NONE, int, float, str, bytes, list, tuple, dict, range, view, generator, bool,
  isNumber, isIterable, asBigInt, asNumber, typeName, pyEq, pyIter, iterToArray,
  pyTruth, rangeLength,
} from '../values.mjs';
import { pyRepr, pyStr } from '../repr.mjs';
import { setFromItems } from '../pyset.mjs';
import { add, compare, mul, pow_, neg } from '../operators.mjs';

export const builtinFunction = (name, call) => ({ type: 'builtin_function', name, call });

const HASH_TABLE_SOURCES = new Set(['set', 'frozenset', 'dict']);

const requireArgs = (name, args, min, max) => {
  if (args.length < min || (max !== undefined && args.length > max)) {
    const expected = max === min ? `exactly ${min}` : `${min} to ${max}`;
    throw typeError(`${name}() takes ${expected} arguments (${args.length} given)`);
  }
};

const asIndex = (v, what = 'object') => {
  if (v.type === 'int' || v.type === 'bool') return asBigInt(v);
  throw typeError(`'${typeName(v)}' ${what} cannot be interpreted as an integer`);
};

const lengthOf = (v) => {
  switch (v.type) {
    case 'str':
      return BigInt(Array.from(v.value).length);
    case 'bytes':
      return BigInt(v.value.length);
    case 'list':
    case 'tuple':
    case 'set':
    case 'frozenset':
    case 'dict_keys':
    case 'dict_values':
    case 'dict_items':
      return BigInt(v.items.length);
    case 'dict':
      return BigInt(v.entries.length);
    case 'range':
      return rangeLength(v);
    default:
      throw typeError(`object of type '${typeName(v)}' has no len()`);
  }
};

export function dictSet(entries, key, value) {
  const hit = entries.find(([k]) => pyEq(k, key));
  if (hit) hit[1] = value;
  else entries.push([key, value]);
}

function dictFromArgs(args, keywords) {
  const entries = [];
  if (args.length > 0) {
    const source = args[0];
    if (source.type === 'dict') {
      for (const [k, v] of source.entries) dictSet(entries, k, v);
    } else {
      for (const item of pyIter(source)) {
        const pair = iterToArray(item);
        if (pair.length !== 2) {
          throw valueError(
            `dictionary update sequence element #${entries.length} has length ${pair.length}; 2 is required`
          );
        }
        dictSet(entries, pair[0], pair[1]);
      }
    }
  }
  for (const { name, value } of keywords) dictSet(entries, str(name), value);
  return dict(entries);
}

const numericSort = (items) => {
  const decorated = items.map((value, index) => ({ value, index }));
  decorated.sort((a, b) => {
    const c = compare(a.value, b.value, '<');
    return c !== 0 ? c : a.index - b.index;
  });
  return decorated.map((d) => d.value);
};

function extremum(name, args, keepLeft) {
  const values = args.length === 1 ? iterToArray(args[0]) : args;
  if (values.length === 0) throw valueError(`${name}() iterable argument is empty`);
  let best = values[0];
  for (const candidate of values.slice(1)) {
    const c = compare(candidate, best, '<');
    if (keepLeft ? c < 0 : c > 0) best = candidate;
  }
  return best;
}

function toInt(v, base) {
  if (v.type === 'str') {
    const text = v.value.trim().replace(/_/g, '');
    const radix = base === undefined ? 10 : Number(asBigInt(base));
    const pattern = {
      10: /^[+-]?\d+$/,
      16: /^[+-]?(0[xX])?[0-9a-fA-F]+$/,
      8: /^[+-]?(0[oO])?[0-7]+$/,
      2: /^[+-]?(0[bB])?[01]+$/,
    }[radix];
    if (!pattern || !pattern.test(text)) {
      throw valueError(`invalid literal for int() with base ${radix}: ${pyRepr(v)}`);
    }
    const sign = text.startsWith('-') ? -1n : 1n;
    const digits = text.replace(/^[+-]/, '').replace(/^0[xXoObB]/, '');
    const prefix = { 10: '', 16: '0x', 8: '0o', 2: '0b' }[radix];
    return int(sign * BigInt(prefix + digits));
  }
  if (v.type === 'float') {
    if (!Number.isFinite(v.value)) {
      throw Number.isNaN(v.value)
        ? valueError('cannot convert float NaN to integer')
        : overflowError('cannot convert float infinity to integer');
    }
    return int(BigInt(Math.trunc(v.value)));
  }
  if (isNumber(v)) return int(asBigInt(v));
  throw typeError(
    `int() argument must be a string, a bytes-like object or a real number, not '${typeName(v)}'`
  );
}

function toFloat(v) {
  if (v.type === 'str') {
    const text = v.value.trim();
    const normalized = text.toLowerCase().replace(/_/g, '');
    if (/^[+-]?(inf|infinity)$/.test(normalized)) {
      return float(normalized.startsWith('-') ? -Infinity : Infinity);
    }
    if (/^[+-]?nan$/.test(normalized)) return float(NaN);
    if (!/^[+-]?(\d+\.?\d*|\.\d+)(e[+-]?\d+)?$/.test(normalized)) {
      throw valueError(`could not convert string to float: ${pyRepr(v)}`);
    }
    return float(Number(normalized));
  }
  if (isNumber(v)) return float(asNumber(v));
  throw typeError(`float() argument must be a string or a real number, not '${typeName(v)}'`);
}

function toBytes(args) {
  if (args.length === 0) return bytes(new Uint8Array(0));
  const source = args[0];
  if (source.type === 'str') throw typeError('string argument without an encoding');
  if (source.type === 'int' || source.type === 'bool') {
    return bytes(new Uint8Array(Number(asBigInt(source))));
  }
  const values = iterToArray(source).map((v) => {
    const n = Number(asIndex(v, 'object'));
    if (n < 0 || n > 255) throw valueError('bytes must be in range(0, 256)');
    return n;
  });
  return bytes(new Uint8Array(values));
}

/** Python 3 round(): half-to-even, returns an int when ndigits is omitted. */
function pyRound(args) {
  const [value, ndigits] = args;
  if (ndigits === undefined) {
    if (value.type !== 'float') return int(asBigInt(value));
    const x = value.value;
    const floor = Math.floor(x);
    const diff = x - floor;
    let result;
    if (diff > 0.5) result = floor + 1;
    else if (diff < 0.5) result = floor;
    else result = floor % 2 === 0 ? floor : floor + 1;
    return int(BigInt(result));
  }
  const digits = Number(asIndex(ndigits));
  if (value.type !== 'float') return int(asBigInt(value));
  const factor = Math.pow(10, digits);
  const scaled = value.value * factor;
  const floor = Math.floor(scaled);
  const diff = scaled - floor;
  let rounded;
  if (diff > 0.5) rounded = floor + 1;
  else if (diff < 0.5) rounded = floor;
  else rounded = floor % 2 === 0 ? floor : floor + 1;
  return float(rounded / factor);
}

function makeRange(args) {
  requireArgs('range', args, 1, 3);
  const bounds = args.map((a) => asIndex(a));
  if (args.length === 1) return range(0n, bounds[0], 1n);
  const step = args.length === 3 ? bounds[2] : 1n;
  if (step === 0n) throw valueError('range() arg 3 must not be zero');
  return range(bounds[0], bounds[1], step);
}

function* enumerateIter(source, start) {
  let index = start;
  for (const item of pyIter(source)) {
    yield tuple([int(index), item]);
    index += 1n;
  }
}

function* zipIter(sources) {
  const iterators = sources.map((s) => pyIter(s));
  for (;;) {
    const row = [];
    for (const iterator of iterators) {
      const step = iterator.next();
      if (step.done) return;
      row.push(step.value);
    }
    yield tuple(row);
  }
}

export const BUILTINS = new Map(
  Object.entries({
    len: (args) => (requireArgs('len', args, 1, 1), int(lengthOf(args[0]))),
    list: (args) => list(args.length === 0 ? [] : iterToArray(args[0])),
    tuple: (args) => tuple(args.length === 0 ? [] : iterToArray(args[0])),
    set: (args) =>
      setFromItems(args.length === 0 ? [] : iterToArray(args[0]), {
        frozen: false,
        sourceIsHashTable: args.length > 0 && HASH_TABLE_SOURCES.has(args[0].type),
      }),
    frozenset: (args) =>
      setFromItems(args.length === 0 ? [] : iterToArray(args[0]), {
        frozen: true,
        sourceIsHashTable: args.length > 0 && HASH_TABLE_SOURCES.has(args[0].type),
      }),
    dict: (args, keywords) => dictFromArgs(args, keywords),
    range: makeRange,
    str: (args) => (args.length === 0 ? str('') : str(pyStr(args[0]))),
    repr: (args) => (requireArgs('repr', args, 1, 1), str(pyRepr(args[0]))),
    int: (args) => (args.length === 0 ? int(0n) : toInt(args[0], args[1])),
    float: (args) => (args.length === 0 ? float(0) : toFloat(args[0])),
    bool: (args) => (args.length === 0 ? bool(false) : bool(pyTruth(args[0]))),
    bytes: toBytes,
    abs: (args) => {
      requireArgs('abs', args, 1, 1);
      const v = args[0];
      if (v.type === 'float') return float(Math.abs(v.value));
      if (isNumber(v)) {
        const n = asBigInt(v);
        return int(n < 0n ? -n : n);
      }
      throw typeError(`bad operand type for abs(): '${typeName(v)}'`);
    },
    sum: (args) => {
      requireArgs('sum', args, 1, 2);
      let total = args[1] ?? int(0n);
      for (const item of pyIter(args[0])) total = add(total, item);
      return total;
    },
    min: (args) => extremum('min', args, true),
    max: (args) => extremum('max', args, false),
    sorted: (args) => (requireArgs('sorted', args, 1, 1), list(numericSort(iterToArray(args[0])))),
    reversed: (args) => {
      requireArgs('reversed', args, 1, 1);
      const items = iterToArray(args[0]).reverse();
      return generator(items[Symbol.iterator](), 'list_reverseiterator');
    },
    enumerate: (args) => {
      requireArgs('enumerate', args, 1, 2);
      const start = args[1] === undefined ? 0n : asIndex(args[1]);
      return generator(enumerateIter(args[0], start), 'enumerate');
    },
    zip: (args) => generator(zipIter(args), 'zip'),
    chr: (args) => {
      requireArgs('chr', args, 1, 1);
      const code = Number(asIndex(args[0]));
