/**
 * Evaluator for the parsed expression AST.
 */

import { typeError, nameError, indexError, keyError, valueError } from '../errors.mjs';
import {
  NONE, TRUE, FALSE, int, str, list, tuple, dict, bool, generator,
  typeName, pyEq, pyIter, iterToArray, pyTruth, asBigInt, rangeLength,
} from '../values.mjs';
import { pyRepr } from '../repr.mjs';
import { makeSetDisplay, makeSetValue } from '../pyset.mjs';
import * as ops from '../operators.mjs';
import { BUILTINS, getAttribute, dictSet } from './builtins.mjs';

const BINARY_OPS = {
  '+': ops.add,
  '-': ops.sub,
  '*': ops.mul,
  '/': ops.trueDiv,
  '//': ops.floorDiv,
  '%': ops.mod,
  '**': ops.pow_,
  '&': ops.bitAnd,
  '|': ops.bitOr,
  '^': ops.bitXor,
  '<<': ops.lshift,
  '>>': ops.rshift,
};

const COMPARE_OPS = {
  '==': ops.eq,
  '!=': ops.ne,
  '<': ops.lt,
  '<=': ops.le,
  '>': ops.gt,
  '>=': ops.ge,
  in: (a, b) => ops.contains(a, b),
  'not in': (a, b) => bool(!pyTruth(ops.contains(a, b))),
  is: (a, b) => bool(a === b || (a.type === b.type && ['NoneType', 'bool'].includes(a.type) && pyEq(a, b))),
  'is not': (a, b) =>
    bool(!(a === b || (a.type === b.type && ['NoneType', 'bool'].includes(a.type) && pyEq(a, b)))),
};

const NAMED_CONSTANTS = {
  None: NONE,
  True: TRUE,
  False: FALSE,
  Ellipsis: { type: 'ellipsis' },
};

/**
 * CPython's AST optimiser folds literals (including negative numbers and simple
 * arithmetic) before code generation; set displays built entirely from such
 * constants take a different construction path, which changes iteration order.
 */
function isConstantNode(node) {
  switch (node.k) {
    case 'Const':
      return true;
    case 'Name':
      return ['None', 'True', 'False'].includes(node.id);
    case 'Paren':
      return isConstantNode(node.value);
    case 'UnaryOp':
      return isConstantNode(node.operand);
    case 'BinOp':
      return isConstantNode(node.left) && isConstantNode(node.right);
    case 'Tuple':
      return node.elts.every(isConstantNode);
    default:
      return false;
  }
}

class Scope {
  constructor(parent = null) {
    this.vars = new Map();
    this.parent = parent;
  }

  lookup(name) {
    for (let scope = this; scope !== null; scope = scope.parent) {
      if (scope.vars.has(name)) return scope.vars.get(name);
    }
    return undefined;
  }

  set(name, value) {
    this.vars.set(name, value);
  }
}

export function evaluate(node, scope = new Scope()) {
  switch (node.k) {
    case 'Const':
      return node.value;
    case 'Paren':
      return evaluate(node.value, scope);
    case 'Name': {
      const local = scope.lookup(node.id);
      if (local !== undefined) return local;
      if (Object.prototype.hasOwnProperty.call(NAMED_CONSTANTS, node.id)) {
        return NAMED_CONSTANTS[node.id];
      }
      const builtin = BUILTINS.get(node.id);
      if (builtin) return builtin;
      throw nameError(`name '${node.id}' is not defined`);
    }
    case 'List':
      return list(node.elts.map((el) => evaluate(el, scope)));
    case 'Tuple':
      return tuple(node.elts.map((el) => evaluate(el, scope)));
    case 'Set':
      return makeSetDisplay(
        node.elts.map((el) => evaluate(el, scope)),
        { allConstant: node.elts.every(isConstantNode) }
      );
    case 'Dict': {
      const entries = [];
      node.keys.forEach((keyNode, i) => {
