 */

import { tokenize } from './tokenizer.mjs';
import { parse } from './parser.mjs';
import { evaluate } from './interpreter.mjs';

export { tokenize, parse, evaluate };

/**
 * @param {string} source  the expression text (`args.a` in the original script)
