/**
 * Synchronous stdout/stderr writers.
 *
 * `process.stdout.write()` is asynchronous when stdout is a pipe, so output can
 * be lost when the process exits immediately afterwards (which this program
 * does for --help and for unhandled exceptions).  Writing through fs.writeSync
 * keeps ordering and guarantees the bytes are flushed before exit.
 */

import { writeSync } from 'node:fs';

const write = (fd, text) => {
  const buffer = Buffer.from(text, 'utf8');
  let offset = 0;
  while (offset < buffer.length) {
    try {
      offset += writeSync(fd, buffer, offset, buffer.length - offset);
    } catch (err) {
      if (err.code === 'EAGAIN') continue; // non-blocking pipe: retry
      if (err.code === 'EPIPE') return; // reader went away
      throw err;
    }
  }
};

export const writeOut = (text) => write(1, text);
export const writeErr = (text) => write(2, text);

