/**
 * The slice of `argparse` this program relies on: one required option with a
 * value, the automatic -h/--help, argparse's usage/help layout, its token
 * classification rules (including the "looks like a negative number" case) and
 * its exit codes (0 for --help, 2 for a usage error).
 */

const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

const terminalWidth = () => {
  const columns = Number.parseInt(process.env.COLUMNS ?? '', 10);
  return (Number.isFinite(columns) && columns > 0 ? columns : 80) - 2;
};

function wrap(text, width) {
  const words = text.split(/\s+/).filter(Boolean);
  if (words.length === 0) return [];
  const lines = [];
  let current = words[0];
  for (const word of words.slice(1)) {
    if (current.length + 1 + word.length <= width) current += ` ${word}`;
    else {
      lines.push(current);
      current = word;
    }
  }
  lines.push(current);
  return lines;
}

class Action {
  constructor(optionStrings, { dest, nargs, help = '', metavar, required = false, kind = 'store' }) {
    this.optionStrings = optionStrings;
    this.dest = dest;
    this.nargs = nargs;
    this.help = help;
    this.metavar = metavar;
    this.required = required;
    this.kind = kind;
  }

  /** e.g. "--a A" or "-h" */
  formatShort(optionString) {
    if (this.nargs === 0) return optionString;
    return `${optionString} ${this.metavar ?? this.dest.toUpperCase()}`;
  }

  /** e.g. "-h, --help" or "--a A" */
  formatInvocation() {
    return this.optionStrings.map((opt) => this.formatShort(opt)).join(', ');
  }

  /** How the action appears inside the usage line. */
  formatUsage() {
    const body = this.formatShort(this.optionStrings[0]);
    return this.required ? body : `[${body}]`;
  }
}

export class UsageError extends Error {}

export class ArgumentParser {
  constructor({ prog, addHelp = true, description = null } = {}) {
    this.prog = prog;
    this.description = description;
    this.actions = [];
    this.optionStringActions = new Map();
    if (addHelp) {
      this.addArgument(['-h', '--help'], {
        nargs: 0,
        kind: 'help',
        help: 'show this help message and exit',
        dest: 'help',
      });
    }
  }

  addArgument(optionStrings, options = {}) {
    const names = Array.isArray(optionStrings) ? optionStrings : [optionStrings];
    const dest =
      options.dest ??
      (names.find((n) => n.startsWith('--')) ?? names[0]).replace(/^-+/, '').replace(/-/g, '_');
    const action = new Action(names, { nargs: 1, ...options, dest });
    this.actions.push(action);
    for (const name of names) this.optionStringActions.set(name, action);
    return action;
  }

  formatUsage() {
    const parts = this.actions.map((a) => a.formatUsage());
    return `usage: ${[this.prog, ...parts].join(' ')}\n`;
  }

  formatHelp() {
    const width = terminalWidth();
    const indent = 2;
    const invocations = this.actions.map((a) => a.formatInvocation());
    const actionMaxLength = Math.max(...invocations.map((i) => i.length + indent));
    const helpPosition = Math.min(actionMaxLength + 2, 24);
    const helpWidth = Math.max(width - helpPosition, 11);

    let out = this.formatUsage();
    if (this.description) out += `\n${this.description}\n`;
    out += '\noptions:\n';
    this.actions.forEach((action, i) => {
