/**
 * Node.js port of dataset/boltons/test11.py
 *
 *     import argparse
 *     from boltons.iterutils import flatten, chunked
 *
 *     parser = argparse.ArgumentParser()
 *     parser.add_argument('--a', type=str, required=True, help='Nested list structure')
 *     args = parser.parse_args()
 *
 *     nested = eval(args.a)
 *     result1 = list(flatten(nested))
 *     print(result1)
 *     ...
 *
 * Run it exactly like the reference binary:
 *     node test11.mjs --a "[1,[2,3],[4,[5,6]],7]"
 */

import { ArgumentParser } from './lib/argparse.mjs';
import { PyError, formatTraceback } from './lib/errors.mjs';
import { writeOut, writeErr } from './lib/stdio.mjs';
import { int, list, iterToArray } from './lib/values.mjs';
import { pyStr } from './lib/repr.mjs';
import { mul } from './lib/operators.mjs';
import { pyEval } from './lib/pyeval/index.mjs';
import { flatten, chunked } from './lib/boltons/iterutils.mjs';

// argparse derives the program name from sys.argv[0]; for the reference
// executable that is "test11_executable".
const PROG = 'test11_executable';
const SCRIPT = 'test11.py';
const TWO = int(2n);

const parser = new ArgumentParser({ prog: PROG });
parser.addArgument(['--a'], {
  required: true,
  help: 'Nested list structure',
  metavar: 'A',
});
const args = parser.parseArgs(process.argv.slice(2));

const print = (value) => writeOut(`${pyStr(value)}\n`);

/** One line of the original script, as the traceback would show it. */
const moduleFrame = (line, source, caret) => ({
  file: SCRIPT,
  line,
  name: '<module>',
  source,
  caret,
});

const BOLTONS_FRAMES = [
  { file: 'boltons/iterutils.py', line: 980, name: 'flatten' },
  { file: 'boltons/iterutils.py', line: 965, name: 'flatten_iter' },
];

/** Frames CPython shows for an exception raised inside eval(). */
