const nested = statement(
  moduleFrame(8, 'nested = eval(args.a)', `${' '.repeat(9)}${'^'.repeat(12)}`),
  evalFrames,
  () => pyEval(args.a)
);

// result1 = list(flatten(nested))  # 展平嵌套列表
const result1 = statement(
  moduleFrame(
    9,
    'result1 = list(flatten(nested))  # 展平嵌套列表',
    `${' '.repeat(15)}${'^'.repeat(15)}`
  ),
  () => BOLTONS_FRAMES,
  () => list(iterToArray(flatten(nested)))
);
print(result1);

// result2 = list(chunked(result1, 2))  # 对展平结果分块
const result2 = list(iterToArray(chunked(result1, 2)));
print(result2);

// result3 = list(chunked(result1, 3))  # 按3分块
const result3 = list(iterToArray(chunked(result1, 3)));
print(result3);

// nested2 = [[x*2 for x in chunk] for chunk in result2]  # 处理分块
const nested2 = statement(
  moduleFrame(
    15,
    'nested2 = [[x*2 for x in chunk] for chunk in result2]  # 处理分块',
    `${' '.repeat(12)}~^~`
