/**
 * Runtime model for Python values.
 *
 * Every Python object is represented as a tagged plain object so that the
 * distinction CPython makes between e.g. `2` and `2.0`, or `True` and `1`,
 * survives into printing and arithmetic.
 *
 *   int      { type: 'int',   value: BigInt }       arbitrary precision
 *   float    { type: 'float', value: Number }
 *   bool     { type: 'bool',  value: Boolean }
 *   None     { type: 'NoneType' }
 *   str      { type: 'str',   value: String }
 *   bytes    { type: 'bytes', value: Uint8Array }
 *   list     { type: 'list',  items: [] }
 *   tuple    { type: 'tuple', items: [] }
 *   set      { type: 'set' | 'frozenset', items: [] }   items in CPython order
 *   dict     { type: 'dict',  entries: [[key, value], ...] }
 *   range    { type: 'range', start, stop, step }        BigInt fields
 *   view     { type: 'dict_keys' | 'dict_values' | 'dict_items', items: [] }
 *   gen      { type: 'generator', iter, name }
 */

import { typeError } from './errors.mjs';

export const NONE = Object.freeze({ type: 'NoneType' });
export const TRUE = Object.freeze({ type: 'bool', value: true });
export const FALSE = Object.freeze({ type: 'bool', value: false });

