export const float = (v) => ({ type: 'float', value: Number(v) });
export const bool = (v) => (v ? TRUE : FALSE);
export const str = (v) => ({ type: 'str', value: String(v) });
export const bytes = (v) => ({ type: 'bytes', value: v instanceof Uint8Array ? v : new Uint8Array(v) });
export const list = (items = []) => ({ type: 'list', items });
export const tuple = (items = []) => ({ type: 'tuple', items });
export const dict = (entries = []) => ({ type: 'dict', entries });
export const range = (start, stop, step) => ({
  type: 'range',
  start: BigInt(start),
  stop: BigInt(stop),
  step: BigInt(step),
});
export const view = (kind, items) => ({ type: kind, items });
export const generator = (iter, name = 'flatten_iter') => ({ type: 'generator', iter, name });

/** The name CPython uses for a value's type in error messages and reprs. */
export function typeName(v) {
  return v.type;
}

const ITERABLE_TYPES = new Set([
  'str', 'bytes', 'list', 'tuple', 'set', 'frozenset', 'dict', 'range',
  'dict_keys', 'dict_values', 'dict_items', 'generator',
]);

export const isIterable = (v) => ITERABLE_TYPES.has(v.type);

/** str / bytes: iterable, yet treated as scalars by boltons' flatten. */
export const isStringLike = (v) => v.type === 'str' || v.type === 'bytes';

export const isNumber = (v) => v.type === 'int' || v.type === 'float' || v.type === 'bool';

/** Numeric value of an int/bool as BigInt. */
export const asBigInt = (v) => (v.type === 'bool' ? (v.value ? 1n : 0n) : v.value);

/** Numeric value of any number-ish value as a JS Number. */
export const asNumber = (v) =>
  v.type === 'float' ? v.value : Number(asBigInt(v));

/** Python's iteration protocol.  Yields Python values. */
export function* pyIter(v) {
  switch (v.type) {
    case 'str':
      // Python iterates code points, which is what for..of does.
      for (const ch of v.value) yield str(ch);
      return;
    case 'bytes':
      for (const b of v.value) yield int(b);
      return;
    case 'list':
    case 'tuple':
      yield* v.items;
      return;
    case 'set':
    case 'frozenset':
    case 'dict_keys':
    case 'dict_values':
    case 'dict_items':
      yield* v.items;
      return;
    case 'dict':
      for (const [k] of v.entries) yield k;
      return;
    case 'range': {
      const { start, stop, step } = v;
      if (step > 0n) for (let i = start; i < stop; i += step) yield int(i);
      else for (let i = start; i > stop; i += step) yield int(i);
      return;
    }
    case 'generator':
      yield* v.iter;
      return;
    default:
      throw typeError(`'${typeName(v)}' object is not iterable`);
  }
}

/** Materialise an iterable into a JS array of Python values. */
export const iterToArray = (v) => Array.from(pyIter(v));

/** Python `==` for the value kinds this program can produce. */
export function pyEq(a, b) {
  if (a === b) return true;
  const an = isNumber(a);
  const bn = isNumber(b);
  if (an && bn) {
    if (a.type === 'float' || b.type === 'float') {
      const x = asNumber(a);
      const y = asNumber(b);
      // NaN never equals anything, including itself.
      return x === y;
    }
