const NON_PRINTABLE_RANGES = [
  // Approximation of Py_UNICODE_ISPRINTABLE() == 0 for the characters that
  // realistically show up: C0/C1 controls, separators and format characters.
  [0x00, 0x1f], [0x7f, 0xa0], [0xad, 0xad], [0x0600, 0x0605], [0x061c, 0x061c],
  [0x06dd, 0x06dd], [0x070f, 0x070f], [0x180e, 0x180e], [0x2000, 0x200f],
  [0x2028, 0x202f], [0x205f, 0x2064], [0x2066, 0x206f], [0x3000, 0x3000],
  [0xd800, 0xdfff], [0xfeff, 0xfeff], [0xfff9, 0xfffb],
];

const isPrintable = (cp) =>
  !NON_PRINTABLE_RANGES.some(([lo, hi]) => cp >= lo && cp <= hi);

/** repr() of a float: shortest round-trip digits, CPython's formatting rules. */
export function floatRepr(value) {
  if (Number.isNaN(value)) return 'nan';
  if (value === Infinity) return 'inf';
  if (value === -Infinity) return '-inf';
  const sign = value < 0 || Object.is(value, -0) ? '-' : '';
  const abs = Math.abs(value);
  if (abs === 0) return `${sign}0.0`;

  // toExponential() without an argument yields the shortest digit string that
  // round-trips, which is exactly what repr() uses.
  const [mantissa, expPart] = abs.toExponential().split('e');
  const digits = mantissa.replace('.', '');
  const decpt = Number(expPart) + 1; // value === 0.<digits> * 10**decpt

  if (decpt <= -4 || decpt > 16) {
    const exp = decpt - 1;
    const head = digits.length > 1 ? `${digits[0]}.${digits.slice(1)}` : digits;
    const expSign = exp < 0 ? '-' : '+';
    const expDigits = String(Math.abs(exp)).padStart(2, '0');
    return `${sign}${head}e${expSign}${expDigits}`;
  }
  if (decpt <= 0) return `${sign}0.${'0'.repeat(-decpt)}${digits}`;
  if (decpt >= digits.length) return `${sign}${digits}${'0'.repeat(decpt - digits.length)}.0`;
  return `${sign}${digits.slice(0, decpt)}.${digits.slice(decpt)}`;
}

