/**
 * Python arithmetic / comparison semantics, including the exact TypeError
 * messages CPython raises for unsupported operand combinations.
 */

import { typeError, zeroDivisionError, valueError } from './errors.mjs';
import {
  int, float, str, bytes, list, tuple, bool,
  isNumber, asBigInt, asNumber, typeName, pyEq, pyIter, isIterable,
} from './values.mjs';

const unsupported = (op, a, b) =>
  typeError(`unsupported operand type(s) for ${op}: '${typeName(a)}' and '${typeName(b)}'`);

const bothInts = (a, b) => isNumber(a) && isNumber(b) && a.type !== 'float' && b.type !== 'float';

const bigFloorDiv = (a, b) => {
  let q = a / b;
  if (a % b !== 0n && a < 0n !== b < 0n) q -= 1n;
  return q;
};

const bigMod = (a, b) => {
  const r = a % b;
  return r !== 0n && r < 0n !== b < 0n ? r + b : r;
};

const repeatSeq = (v, countValue) => {
  const n = Number(asBigInt(countValue));
  const times = n > 0 ? n : 0;
  switch (v.type) {
    case 'str':
      return str(v.value.repeat(times));
    case 'bytes': {
      const out = new Uint8Array(v.value.length * times);
      for (let i = 0; i < times; i++) out.set(v.value, i * v.value.length);
      return bytes(out);
    }
    case 'list': {
      const items = [];
      for (let i = 0; i < times; i++) items.push(...v.items);
      return list(items);
    }
    case 'tuple': {
      const items = [];
      for (let i = 0; i < times; i++) items.push(...v.items);
      return tuple(items);
    }
    default:
      return null;
  }
};

const isSequence = (v) => ['str', 'bytes', 'list', 'tuple'].includes(v.type);
const isIntLike = (v) => v.type === 'int' || v.type === 'bool';

export function mul(a, b) {
  if (isNumber(a) && isNumber(b)) {
    if (bothInts(a, b)) return int(asBigInt(a) * asBigInt(b));
    return float(asNumber(a) * asNumber(b));
  }
  if (isSequence(a) && isIntLike(b)) return repeatSeq(a, b);
  if (isIntLike(a) && isSequence(b)) return repeatSeq(b, a);
  throw unsupported('*', a, b);
}

export function add(a, b) {
  if (isNumber(a) && isNumber(b)) {
    if (bothInts(a, b)) return int(asBigInt(a) + asBigInt(b));
    return float(asNumber(a) + asNumber(b));
  }
  if (a.type === 'str' && b.type === 'str') return str(a.value + b.value);
  if (a.type === 'bytes' && b.type === 'bytes') {
    const out = new Uint8Array(a.value.length + b.value.length);
    out.set(a.value);
    out.set(b.value, a.value.length);
    return bytes(out);
  }
  if (a.type === 'list' && b.type === 'list') return list([...a.items, ...b.items]);
  if (a.type === 'tuple' && b.type === 'tuple') return tuple([...a.items, ...b.items]);
  if (['str', 'bytes', 'list', 'tuple'].includes(a.type)) {
    throw typeError(`can only concatenate ${typeName(a)} (not "${typeName(b)}") to ${typeName(a)}`);
  }
  throw unsupported('+', a, b);
}

export function sub(a, b) {
  if (isNumber(a) && isNumber(b)) {
    if (bothInts(a, b)) return int(asBigInt(a) - asBigInt(b));
    return float(asNumber(a) - asNumber(b));
  }
  throw unsupported('-', a, b);
}

export function trueDiv(a, b) {
  if (isNumber(a) && isNumber(b)) {
    const y = asNumber(b);
    if (y === 0) {
      throw zeroDivisionError(
        bothInts(a, b) ? 'division by zero' : 'float division by zero'
      );
    }
    return float(asNumber(a) / y);
  }
  throw unsupported('/', a, b);
}

export function floorDiv(a, b) {
  if (isNumber(a) && isNumber(b)) {
    if (bothInts(a, b)) {
      const y = asBigInt(b);
      if (y === 0n) throw zeroDivisionError('integer division or modulo by zero');
      return int(bigFloorDiv(asBigInt(a), y));
    }
    const y = asNumber(b);
    if (y === 0) throw zeroDivisionError('float floor division by zero');
    return float(Math.floor(asNumber(a) / y));
  }
  throw unsupported('//', a, b);
}

export function mod(a, b) {
  if (isNumber(a) && isNumber(b)) {
    if (bothInts(a, b)) {
      const y = asBigInt(b);
      if (y === 0n) throw zeroDivisionError('integer modulo by zero');
      return int(bigMod(asBigInt(a), y));
    }
    const y = asNumber(b);
    if (y === 0) throw zeroDivisionError('float modulo');
    const x = asNumber(a);
    const r = x - Math.floor(x / y) * y;
    return float(r);
  }
  throw unsupported('%', a, b);
}

export function pow_(a, b) {
  if (isNumber(a) && isNumber(b)) {
    if (bothInts(a, b)) {
      const base = asBigInt(a);
      const exp = asBigInt(b);
      if (exp >= 0n) return int(base ** exp);
      if (base === 0n) throw zeroDivisionError('0.0 cannot be raised to a negative power');
      return float(Math.pow(Number(base), Number(exp)));
    }
    return float(Math.pow(asNumber(a), asNumber(b)));
  }
  throw unsupported('**', a, b);
}

export function neg(a) {
  if (a.type === 'float') return float(-a.value);
  if (isNumber(a)) return int(-asBigInt(a));
  throw typeError(`bad operand type for unary -: '${typeName(a)}'`);
}

export function pos(a) {
  if (a.type === 'float') return float(a.value);
  if (isNumber(a)) return int(asBigInt(a));
  throw typeError(`bad operand type for unary +: '${typeName(a)}'`);
}

export function invert(a) {
  if (isNumber(a) && a.type !== 'float') return int(-asBigInt(a) - 1n);
  throw typeError(`bad operand type for unary ~: '${typeName(a)}'`);
}

const intOnly = (op, a, b) => {
  if (!bothInts(a, b)) throw unsupported(op, a, b);
};

export function bitAnd(a, b) {
  intOnly('&', a, b);
  return int(asBigInt(a) & asBigInt(b));
}
export function bitOr(a, b) {
  intOnly('|', a, b);
  return int(asBigInt(a) | asBigInt(b));
}
export function bitXor(a, b) {
  intOnly('^', a, b);
  return int(asBigInt(a) ^ asBigInt(b));
}
export function lshift(a, b) {
  intOnly('<<', a, b);
  if (asBigInt(b) < 0n) throw valueError('negative shift count');
  return int(asBigInt(a) << asBigInt(b));
}
export function rshift(a, b) {
  intOnly('>>', a, b);
  if (asBigInt(b) < 0n) throw valueError('negative shift count');
  return int(asBigInt(a) >> asBigInt(b));
}

/** Three-way comparison for `<`, `<=`, `>`, `>=`; raises like CPython. */
function compare(a, b, op) {
  if (isNumber(a) && isNumber(b)) {
    if (bothInts(a, b)) {
      const x = asBigInt(a);
      const y = asBigInt(b);
      return x < y ? -1 : x > y ? 1 : 0;
    }
    const x = asNumber(a);
    const y = asNumber(b);
    if (Number.isNaN(x) || Number.isNaN(y)) return NaN;
    return x < y ? -1 : x > y ? 1 : 0;
  }
  if (a.type === 'str' && b.type === 'str') {
    // Python compares code point by code point.
    const xs = Array.from(a.value, (c) => c.codePointAt(0));
    const ys = Array.from(b.value, (c) => c.codePointAt(0));
    return lexCompare(xs, ys, (x, y) => (x < y ? -1 : x > y ? 1 : 0));
  }
  if ((a.type === 'list' && b.type === 'list') || (a.type === 'tuple' && b.type === 'tuple')) {
    return lexCompare(a.items, b.items, (x, y) => compare(x, y, op));
  }
  throw typeError(
    `'${op}' not supported between instances of '${typeName(a)}' and '${typeName(b)}'`
  );
}

function lexCompare(xs, ys, cmp) {
  const n = Math.min(xs.length, ys.length);
  for (let i = 0; i < n; i++) {
    const c = cmp(xs[i], ys[i]);
    if (c !== 0) return c;
  }
  return xs.length < ys.length ? -1 : xs.length > ys.length ? 1 : 0;
}

export const lt = (a, b) => bool(compare(a, b, '<') < 0);
export const le = (a, b) => bool(compare(a, b, '<=') <= 0);
export const gt = (a, b) => bool(compare(a, b, '>') > 0);
export const ge = (a, b) => bool(compare(a, b, '>=') >= 0);
export const eq = (a, b) => bool(pyEq(a, b));
export const ne = (a, b) => bool(!pyEq(a, b));

export function contains(needle, haystack) {
  if (haystack.type === 'str') {
    if (needle.type !== 'str') {
      throw typeError(
