/**
 * Reproduction of CPython's `set` hash table, so that the iteration order of a
 * set matches the reference interpreter byte for byte.
 *
 * Table mechanics (Objects/setobject.c):
 *   - `size` slots, a key lands on `hash & mask`;
 *   - on collision up to LINEAR_PROBES following slots are scanned, but only
 *     while the whole run stays inside the table, then the probe jumps with
 *     `i = i*5 + 1 + perturb`, `perturb >>= 5`;
 *   - the table grows to `4 * used` (rounded up to a power of two) as soon as
 *     `fill*5 >= mask*3`;
 *   - iteration walks the slots in index order.
 *
 * How a set gets built matters as much as the table itself:
 *   - `{a, b, c}` with more than two constant elements is folded by the
 *     compiler into a frozenset constant, which the marshalled .pyc rebuilds by
 *     re-adding the elements in the *constant's* iteration order, and the code
 *     then does BUILD_SET + SET_UPDATE, i.e. set_merge() into an empty set;
 *   - set_merge() pre-sizes the destination to `2 * used`, then either copies
 *     the slots verbatim (when both masks agree) or re-inserts with
 *     set_insert_clean();
 *   - `set(iterable)` over a non-set iterable simply adds one key at a time.
 *
 * That is why `{0,8,16,24,32}` iterates as 0, 32, 16, 8, 24 while
 * `set([0,8,16,24,32])` iterates as 0, 32, 8, 16, 24.
 */

import { pyEq } from './values.mjs';
import { pyHash, toUnsigned64 } from './hashing.mjs';

const MINSIZE = 8;
const LINEAR_PROBES = 9;
const PERTURB_SHIFT = 5n;

class SetTable {
  constructor(size = MINSIZE) {
    this.#reset(size);
  }

  #reset(size) {
    this.mask = size - 1;
    this.table = new Array(size).fill(null);
    this.fill = 0;
    this.used = 0;
  }

  /** set_add_entry */
  add(key, hash) {
    const uhash = toUnsigned64(hash);
    const mask = BigInt(this.mask);
    let i = Number(uhash & mask);
    let perturb = uhash;
    for (;;) {
      let probes = i + LINEAR_PROBES <= this.mask ? LINEAR_PROBES : 0;
      let j = i;
      for (;;) {
        const entry = this.table[j];
        if (entry === null) {
          this.#insertFound(j, key, hash);
          return;
        }
        if (entry.hash === hash && pyEq(entry.key, key)) return; // already present
        j++;
        if (probes-- === 0) break;
      }
      perturb >>= PERTURB_SHIFT;
      i = Number((BigInt(i) * 5n + 1n + perturb) & mask);
    }
  }

  #insertFound(slot, key, hash) {
    this.table[slot] = { key, hash };
    this.fill++;
    this.used++;
    if (this.fill * 5 >= this.mask * 3) {
      this.#resize(this.used > 50000 ? this.used * 2 : this.used * 4);
    }
  }

  /** set_table_resize */
  #resize(minused) {
    let newsize = MINSIZE;
    while (newsize <= minused) newsize <<= 1;
    const oldEntries = this.entries();
    this.#reset(newsize);
    for (const entry of oldEntries) this.insertClean(entry.key, entry.hash);
    this.fill = oldEntries.length;
    this.used = oldEntries.length;
  }

  /** set_insert_clean: the keys are known to be unique, so no comparisons. */
  insertClean(key, hash) {
    const uhash = toUnsigned64(hash);
    const mask = BigInt(this.mask);
    let i = Number(uhash & mask);
    let perturb = uhash;
    for (;;) {
      if (this.table[i] === null) {
        this.table[i] = { key, hash };
        return;
      }
      if (i + LINEAR_PROBES <= this.mask) {
        for (let j = 1; j <= LINEAR_PROBES; j++) {
          if (this.table[i + j] === null) {
            this.table[i + j] = { key, hash };
            return;
          }
        }
      }
      perturb >>= PERTURB_SHIFT;
      i = Number((BigInt(i) * 5n + 1n + perturb) & mask);
    }
  }

  /** The single bulk resize set_merge()/set_update_internal() do up front. */
  presize(otherUsed) {
    if ((this.fill + otherUsed) * 5 >= this.mask * 3) {
      this.#resize((this.used + otherUsed) * 2);
    }
  }

  entries() {
    return this.table.filter((entry) => entry !== null);
  }

  keys() {
    return this.entries().map((entry) => entry.key);
  }
}

const allHashesKnown = (elements) => elements.every((e) => pyHash(e) !== null);

function dedupInsertionOrder(elements) {
  const out = [];
  for (const el of elements) if (!out.some((seen) => pyEq(seen, el))) out.push(el);
  return out;
}

/**
 * A set value keeps the table geometry alongside its members: `mask` is needed
 * because set_merge()'s verbatim-copy shortcut only applies when the source and
 * destination masks agree.  `mask === null` marks a container whose order could
 * not be modelled (str/bytes members are hashed with a per-process salt).
 */
const setValue = (items, mask, frozen) => ({
  type: frozen ? 'frozenset' : 'set',
  items,
  mask,
  used: items.length,
});

/** Add keys one at a time to a fresh table: BUILD_SET, set(list), ... */
export function makeSetValue(elements, { frozen = false } = {}) {
  if (!allHashesKnown(elements)) return setValue(dedupInsertionOrder(elements), null, frozen);
  const table = new SetTable();
  for (const el of elements) table.add(el, pyHash(el));
  return setValue(table.keys(), table.mask, frozen);
}

/** set_merge(): source is another set/frozenset. */
function mergeFromSet(source, frozen) {
  if (source.items.length === 0) return setValue([], MINSIZE - 1, frozen);
  if (source.mask === null || !allHashesKnown(source.items)) {
    return setValue([...source.items], null, frozen);
  }
  const table = new SetTable();
  table.presize(source.items.length);
  if (table.mask === source.mask) {
    // Identical geometry and an empty destination: the slots are copied as-is.
    return setValue([...source.items], source.mask, frozen);
  }
  for (const item of source.items) table.insertClean(item, pyHash(item));
  return setValue(table.keys(), table.mask, frozen);
}

/** set_update_internal()'s dict branch: pre-size, then normal insertions. */
function mergeFromDictKeys(keys, frozen) {
  if (!allHashesKnown(keys)) return setValue(dedupInsertionOrder(keys), null, frozen);
  const table = new SetTable();
  table.presize(keys.length);
  for (const key of keys) table.add(key, pyHash(key));
  return setValue(table.keys(), table.mask, frozen);
}

/**
 * A `{...}` display.  With more than two constant elements the compiler folds
 * the literal into a frozenset constant; unmarshalling that constant rebuilds
 * it element by element, and SET_UPDATE then merges it into the empty set left
 * by BUILD_SET 0.  All three steps affect the final slot layout.
 */
export function makeSetDisplay(elements, { allConstant = false } = {}) {
  if (elements.length > 2 && allConstant) {
    const compiled = makeSetValue(elements, { frozen: true });
    const unmarshalled = makeSetValue(compiled.items, { frozen: true });
    return mergeFromSet(unmarshalled, false);
  }
  return makeSetValue(elements, { frozen: false });
}

/**
 * set()/frozenset() applied to an already materialised iterable.
 *
 * @param {object[]} items   the source's elements in iteration order
 * @param {{frozen?: boolean, source?: object|null}} options
 *        `source` is the original container, used to pick the construction path.
 */
export function setFromItems(items, { frozen = false, source = null } = {}) {
  if (source !== null && (source.type === 'set' || source.type === 'frozenset')) {
    return mergeFromSet(source, frozen);
  }
  if (source !== null && source.type === 'dict') return mergeFromDictKeys(items, frozen);
  return makeSetValue(items, { frozen });
}

