/**
 * Reproduction of CPython's `set` hash table so that iteration order of a set
 * literal matches the reference interpreter byte for byte.
 *
 * The table is an open-addressed array of `size` slots.  A new key lands on
 * `hash & mask`; on collision CPython first scans up to LINEAR_PROBES following
 * slots (only while the whole run stays inside the table) and then jumps with
 * `i = i*5 + 1 + perturb`, shifting `perturb` right by 5 each round.  The table
 * grows to `4 * used` rounded up to a power of two once `fill*5 >= mask*3`.
 * Iteration simply walks the slots in index order, which is why `{0,8,16,24,32}`
 * prints as `{0, 32, 16, 8, 24}`.
 */

import { pyEq } from './values.mjs';
import { pyHash, toUnsigned64 } from './hashing.mjs';

const MINSIZE = 8;
const LINEAR_PROBES = 9;
const PERTURB_SHIFT = 5n;

class SetTable {
  constructor(size = MINSIZE) {
    this.#reset(size);
  }

  #reset(size) {
    this.mask = size - 1;
    this.table = new Array(size).fill(null);
    this.fill = 0;
    this.used = 0;
  }

  /** set_add_entry */
  add(key, hash) {
    const uhash = toUnsigned64(hash);
    let mask = BigInt(this.mask);
    let i = Number(uhash & mask);
    let perturb = uhash;
    for (;;) {
      let probes = i + LINEAR_PROBES <= this.mask ? LINEAR_PROBES : 0;
      let j = i;
      for (;;) {
        const entry = this.table[j];
        if (entry === null) {
          this.#insertFound(j, key, hash);
          return;
        }
        if (entry.hash === hash && pyEq(entry.key, key)) return; // already present
        j++;
        if (probes-- === 0) break;
      }
      perturb >>= PERTURB_SHIFT;
      i = Number((BigInt(i) * 5n + 1n + perturb) & mask);
    }
  }

  #insertFound(slot, key, hash) {
    this.table[slot] = { key, hash };
    this.fill++;
    this.used++;
    if (this.fill * 5 >= this.mask * 3) {
      this.#resize(this.used > 50000 ? this.used * 2 : this.used * 4);
    }
  }

  /** set_table_resize */
  #resize(minused) {
    let newsize = MINSIZE;
    while (newsize <= minused) newsize <<= 1;
    const oldEntries = this.table.filter((e) => e !== null);
    this.#reset(newsize);
    for (const entry of oldEntries) this.#insertClean(entry.key, entry.hash);
    this.fill = oldEntries.length;
    this.used = oldEntries.length;
  }

  /** set_insert_clean: no equality checks, the keys are known to be unique. */
  #insertClean(key, hash) {
    const uhash = toUnsigned64(hash);
    const mask = BigInt(this.mask);
    let i = Number(uhash & mask);
    let perturb = uhash;
    for (;;) {
      if (this.table[i] === null) {
        this.table[i] = { key, hash };
        return;
      }
      if (i + LINEAR_PROBES <= this.mask) {
        for (let j = 1; j <= LINEAR_PROBES; j++) {
          if (this.table[i + j] === null) {
            this.table[i + j] = { key, hash };
            return;
          }
        }
      }
      perturb >>= PERTURB_SHIFT;
      i = Number((BigInt(i) * 5n + 1n + perturb) & mask);
    }
  }

  /**
   * set_update_internal's up-front resize, used when the source is another
   * set/frozenset or a dict (CPython avoids incremental growth there).
   */
  presize(otherUsed) {
    if ((this.fill + otherUsed) * 5 >= this.mask * 3) {
      this.#resize((this.used + otherUsed) * 2);
    }
  }

  keys() {
    const out = [];
    for (const entry of this.table) if (entry !== null) out.push(entry.key);
    return out;
  }
}

const allHashesKnown = (elements) => elements.every((e) => pyHash(e) !== null);

function dedupInsertionOrder(elements) {
  const out = [];
  for (const el of elements) if (!out.some((seen) => pyEq(seen, el))) out.push(el);
  return out;
}

function tableOrder(elements, presizeFrom) {
  const table = new SetTable();
  if (presizeFrom !== null) table.presize(presizeFrom);
  for (const el of elements) table.add(el, pyHash(el));
  return table.keys();
}

/**
 * Build a set value.
 *
 * @param {object[]} elements  candidate members, in insertion order
 * @param {{frozen?: boolean, presizeFrom?: number|null}} options
 *        `presizeFrom` mirrors set_update_internal's bulk resize; pass the
 *        source container's length when the source is a set/frozenset/dict.
 */
export function makeSetValue(elements, { frozen = false, presizeFrom = null } = {}) {
  const items = allHashesKnown(elements)
    ? tableOrder(elements, presizeFrom)
    : dedupInsertionOrder(elements);
  return { type: frozen ? 'frozenset' : 'set', items };
}

