/**
 * Random Python-expression generator for differential fuzzing.
 * Prints one expression per line.
 */
const count = Number(process.argv[2] ?? 200);
const seed = Number(process.argv[3] ?? 12345);

let state = seed >>> 0;
const rnd = () => {
  state = (state * 1103515245 + 12345) >>> 0;
  return state / 4294967296;
};
const pick = (arr) => arr[Math.floor(rnd() * arr.length)];
const rint = (lo, hi) => lo + Math.floor(rnd() * (hi - lo + 1));

const scalar = () => {
  switch (rint(0, 9)) {
    case 0: return String(rint(-50, 50));
    case 1: return String(rint(0, 5) * 8); // collision-prone in the set table
    case 2: return `${rint(-20, 20)}.${rint(0, 999)}`;
    case 3: return `'${'abc'.slice(0, rint(1, 3))}${rint(0, 9)}'`;
    case 4: return pick(['True', 'False']);
    case 5: return String(rint(0, 3) * 16 + rint(0, 1));
    case 6: return `${rint(1, 9)}e${rint(-8, 18)}`;
    case 7: return String(10n ** BigInt(rint(15, 25)) + BigInt(rint(0, 9)));
    case 8: return `${rint(1, 4)}/${rint(1, 7)}`;
    default: return String(rint(0, 100));
  }
};

const container = (depth) => {
  const n = rint(0, depth === 0 ? 6 : 4);
  const kids = Array.from({ length: n }, () => expr(depth + 1));
  switch (rint(0, 7)) {
    case 0: return `(${kids.join(',')}${n === 1 ? ',' : ''})`;
    case 1: return `{${kids.join(',')}}` === '{}' ? 'set()' : `{${kids.join(',')}}`;
    case 2: return `set([${kids.join(',')}])`;
    case 3: return `frozenset([${kids.join(',')}])`;
    case 4: return `{${kids.map((k, i) => `${i}:${k}`).join(',')}}`;
    case 5: return `list(range(${rint(0, 8)}))`;
    case 6: return `[${kids.join(',')}]*${rint(0, 3)}`;
    default: return `[${kids.join(',')}]`;
  }
};

const expr = (depth = 0) => {
  if (depth >= 3 || (depth > 0 && rnd() < 0.45)) return scalar();
  return container(depth);
};

for (let i = 0; i < count; i++) {
  const top = rnd() < 0.85 ? `[${Array.from({ length: rint(0, 5) }, () => expr(1)).join(',')}]` : expr(0);
  console.log(top);
}

